require "application_system_test_case"

class InstantNoShiftTest < ApplicationSystemTestCase
  include ActionView::RecordIdentifier

  test "board updates instantly before save finishes and nothing shifts afterwards" do
    sign_in_as(users(:david))
    board = boards(:writebook)
    visit board_url(board)

    buy_domain = cards(:buy_domain)
    logo = cards(:logo)
    layout = cards(:layout)
    triage = columns(:writebook_triage)

    # Expand Triage column
    find("##{dom_id(triage)} .cards__expander").click
    assert_selector "##{dom_id(triage)}.is-expanded"
    # Wait for expand transition to settle
    sleep 0.4

    # Pause fetch requests in JS
    page.execute_script(<<~JS)
      window.__originalFetch = window.fetch;
      window.__pendingFetches = [];
      window.fetch = function(...args) {
        return new Promise((resolve, reject) => {
          window.__pendingFetches.push(() => window.__originalFetch(...args).then(resolve, reject));
        });
      };
    JS

    # Perform drag from Maybe to Triage
    find("#maybe ##{dom_id(buy_domain, :article)}").drag_to(find("##{dom_id(triage)}"))

    # Verify save has NOT happened on server yet
    assert_nil buy_domain.reload.column
    pending_count = page.evaluate_script("window.__pendingFetches.length")
    assert_equal 1, pending_count, "Expected 1 paused fetch request"

    # Yet the board DOM is ALREADY updated!
    assert_no_selector "#maybe ##{dom_id(buy_domain, :article)}"
    assert_selector "##{dom_id(triage)} ##{dom_id(buy_domain, :article)}"

    ids_before_save = all("##{dom_id(triage)} .cards__list .card").map { |el| el[:id] }
    assert_equal [ dom_id(logo, :article), dom_id(buy_domain, :article), dom_id(layout, :article) ], ids_before_save

    rects_before_save = page.evaluate_script(<<~JS)
