        const r = el.getBoundingClientRect();
        return { id: el.id, top: Math.round(r.top), left: Math.round(r.left), width: Math.round(r.width), color: el.style.getPropertyValue("--card-color") };
      })
    JS

    # Now release the save request and restore fetch
    page.execute_script(<<~JS)
      window.fetch = window.__originalFetch;
      window.__pendingFetches.forEach(fn => fn());
